function currentRecord(row: CurrentRow): QueryInventoryRecord {
  const [
    file,
    symbol,
    line,
    column,
    family,
    operation,
    kind,
    statementRole,
    projection,
    filter,
    join,
    order,
    bound,
    queryCountBudget,
    cache,
    freshness,
    transaction,
    constraint,
    budgetId,
    plannedShapeId,
    fingerprintKey,
    owner,
    disposition,
  ] = row;
  return fullRecord({
    id: `${file}#${symbol}:L${line}:C${column}:${decode(FAMILY, family)}:${decode(OPERATION, operation)}`,
    recordState: "current",
    file,
    symbol,
    line,
    column,
    family,
    operation,
    kind,
    statementRole,
    projection,
    filter,
    join,
    order,
    bound,
    queryCountBudget,
    cache,
    freshness,
    transaction,
    constraint,
    budgetId,
    plannedShapeId,
    fingerprintKey,
    owner,
    disposition,
  });
}

