export function createTask551InvalidLifecycleSources(source: string): readonly string[] {
  return Object.freeze([
    'let loader = () => import("./client") as Promise<unknown>; function setDatabaseClientModuleForTests(next: (() => Promise<unknown>) | null) { loader = next ?? (() => import("./client") as Promise<unknown>); } async function loadClientModule() { return loader?.(); }',
    source.replace(
      "const clientModule = await loadClientModule();\n  await clientModule.closeAllDatabaseClientsWithin(budgetMs);",
      "const module = await loadClientModule();\n  await module.db.select();"
    ),
    source.replace("async function loadClientModule", "export async function loadClientModule"),
    source.replace(
      "const clientModule = await loadClientModule();",
      "const forward = loadClientModule; const clientModule = await loadClientModule();"
    ),
    source.replace(
      "const clientModule = await loadClientModule();\n      await clientModule.verifyDatabaseSessions();",
      "const loadClientModule = async () => ({}) as DatabaseClientModule;\n      const clientModule = await loadClientModule();\n      await clientModule.verifyDatabaseSessions();"
    ),
  ]);
}

export type Task551StoredReceiptMutation = Readonly<{
  actual: Readonly<Record<string, unknown>>;
  code: "query_inventory_final_receipt_missing" | "query_inventory_phase_invalid";
  field: keyof QueryInventoryReceipt;
}>;

export function createTask551StoredReceiptIdentityMutations(
  receipt: QueryInventoryReceipt
): readonly Task551StoredReceiptMutation[] {
  const alternateDigest = (value: string) =>
    value === "0".repeat(64) ? "1".repeat(64) : "0".repeat(64);
  const mutation = (
    field: keyof QueryInventoryReceipt,
    value: unknown,
    code: Task551StoredReceiptMutation["code"] = "query_inventory_final_receipt_missing"
  ): Task551StoredReceiptMutation =>
    Object.freeze({ actual: Object.freeze({ ...receipt, [field]: value }), code, field });
  return Object.freeze([
    mutation("schemaVersion", 2, "query_inventory_phase_invalid"),
    mutation("phase", receipt.phase === "initial" ? "final" : "initial"),
    mutation("sourceTreeDigest", alternateDigest(receipt.sourceTreeDigest)),
    mutation("inventoryDigest", alternateDigest(receipt.inventoryDigest)),
    mutation("plannedDeltaDigest", alternateDigest(receipt.plannedDeltaDigest)),
    mutation("fingerprintAssociationDigest", alternateDigest(receipt.fingerprintAssociationDigest)),
    mutation("discoveredCount", receipt.discoveredCount + 1),
    mutation("ownedCount", receipt.ownedCount + 1),
    mutation("plannedDeltaCount", receipt.plannedDeltaCount + 1),
    mutation("adminReadPlannedCount", receipt.adminReadPlannedCount + 1),
    mutation("legacyPlannedCount", receipt.legacyPlannedCount + 1),
  ]);
}

export function createTask551FixtureDiscoveredCallers(): readonly DiscoveredCaller[] {
  return Object.freeze(
    TASK551_QUERY_INVENTORY.map(({ id, source, caller }) => {
      if (source.line === null || source.column === null)
        fail("query_inventory_invalid", "fixture-current-anchor");
      return Object.freeze({
        id,
        source: Object.freeze({ ...source, line: source.line, column: source.column }),
        caller,
      });
    })
  );
}

/** Caller-enum builder: re-anchors the first reviewed current record at any family/operation pair, unvalidated. */
export function createTask551CallerPairRecord(
  family: CallerFamily,
  operation: CallerOperation
): QueryInventoryRecord {
  const base =
    TASK551_QUERY_INVENTORY.find((record) => record.disposition !== "external-handoff") ??
    fail("query_inventory_invalid", "fixture-current-anchor");
  const source = { ...base.source, line: base.source.line!, column: base.source.column! };
  const caller = { family, operation };
  return { ...base, source, caller, id: canonicalRecordId(source, caller) };
}

export type Task551CanonicalReceiptMutation = Readonly<{
  fields: readonly string[];
  discovered: readonly DiscoveredCaller[];
  current: readonly QueryInventoryRecord[];
  planned: readonly QueryInventoryRecord[];
  associations: Task551FingerprintAssociationMap;
}>;

