type ReceiptMutationInput = Readonly<Partial<Omit<Task551CanonicalReceiptMutation, "fields">>>;

function task551ReceiptRecord(
  records: readonly QueryInventoryRecord[],
  predicate: (record: QueryInventoryRecord) => boolean
): QueryInventoryRecord {
  const record = records.find(predicate);
  return record ?? fail("query_inventory_invalid", "fixture-receipt-record");
}

function replaceTask551ReceiptRecord(
  records: readonly QueryInventoryRecord[],
  original: QueryInventoryRecord,
  changed: QueryInventoryRecord
): readonly QueryInventoryRecord[] {
  return Object.freeze(records.map((record) => (record.id === original.id ? changed : record)));
}

function task551ReceiptAssociations(
  current: readonly QueryInventoryRecord[],
  planned: readonly QueryInventoryRecord[]
): Task551FingerprintAssociationMap {
  return Object.freeze(
    Object.fromEntries(
      [...current, ...planned]
        .filter((record) => record.telemetryFingerprintKey !== null)
        .map((record) => [record.id, record.telemetryFingerprintKey!])
    )
  );
}

function createTask551ReceiptMutation(
  fields: readonly string[],
  input: ReceiptMutationInput = {}
): Task551CanonicalReceiptMutation {
  const current = input.current ?? TASK551_QUERY_INVENTORY;
  const planned = input.planned ?? PLANNED_QUERY_DELTAS;
  return Object.freeze({
    fields: Object.freeze([...fields]),
    discovered: input.discovered ?? createTask551FixtureDiscoveredCallers(),
    current,
    planned,
    associations: input.associations ?? task551ReceiptAssociations(current, planned),
  });
}

function validTask551CurrentMutation(
  changes: Readonly<Partial<QueryInventoryRecord>>
): QueryInventoryRecord {
  const base = task551ReceiptRecord(
    TASK551_QUERY_INVENTORY,
    (record) => record.disposition !== "external-handoff"
  );
  const source = changes.source ?? base.source;
  const caller = changes.caller ?? base.caller;
  if (source.line === null || source.column === null)
    fail("query_inventory_invalid", "fixture-current-anchor");
  const anchor = {
    file: source.file,
    symbol: source.symbol,
    line: source.line,
    column: source.column,
  };
  return validateInventoryRecord({
    ...base,
    ...changes,
    source,
    caller,
    id: canonicalRecordId(anchor, caller),
  });
}

function validTask551PlannedMutation(
  changes: Readonly<Partial<QueryInventoryRecord>>
): QueryInventoryRecord {
  const base = task551ReceiptRecord(PLANNED_QUERY_DELTAS, () => true);
  return validateInventoryRecord({
    ...base,
    ...changes,
    source: changes.source ?? base.source,
    caller: changes.caller ?? base.caller,
  });
}

function removeTask551Association(
  associations: Task551FingerprintAssociationMap
): Task551FingerprintAssociationMap {
  const [id] = Object.keys(associations);
  if (id === undefined) fail("query_inventory_invalid", "fixture-association");
  const { [id]: _removed, ...remaining } = associations;
  return Object.freeze(remaining);
}

/** Valid canonical input changes for every mutable receipt digest field. */
export function createTask551CanonicalReceiptMutations(): readonly Task551CanonicalReceiptMutation[] {
  const current = task551ReceiptRecord(
    TASK551_QUERY_INVENTORY,
    (record) => record.disposition !== "external-handoff"
  );
  const planned = task551ReceiptRecord(PLANNED_QUERY_DELTAS, () => true);
  const adminPlanned = task551ReceiptRecord(
    PLANNED_QUERY_DELTAS,
    (record) => record.owner === "TASK-551-03-L02"
  );
  const legacyPlanned = task551ReceiptRecord(
    PLANNED_QUERY_DELTAS,
    (record) => record.owner !== "TASK-551-03-L02"
  );
  const discovered = createTask551FixtureDiscoveredCallers();
  const firstDiscovered = discovered[0] ?? fail("query_inventory_invalid", "fixture-discovery");
  const mutateDiscovered = (
    source: DiscoveredCaller["source"],
    caller = firstDiscovered.caller
  ): readonly DiscoveredCaller[] =>
    Object.freeze([
      Object.freeze({
        id: canonicalRecordId(source, caller),
        source: Object.freeze(source),
        caller,
      }),
      ...discovered.slice(1),
    ]);
  const changedCurrent = (
    changes: Readonly<Partial<QueryInventoryRecord>>
  ): readonly QueryInventoryRecord[] =>
    replaceTask551ReceiptRecord(
      TASK551_QUERY_INVENTORY,
      current,
      validTask551CurrentMutation(changes)
    );
  const changedPlanned = (
    changes: Readonly<Partial<QueryInventoryRecord>>
  ): readonly QueryInventoryRecord[] =>
    replaceTask551ReceiptRecord(
      PLANNED_QUERY_DELTAS,
      planned,
      validTask551PlannedMutation(changes)
    );
  const currentAsPlanned = validateInventoryRecord({
    ...current,
    recordState: "planned",
    id: "receipt-current-as-planned",
    source: {
      file: "core/services/receiptState.ts",
      symbol: "receiptState",
      line: null,
      column: null,
    },
    plannedShapeId: "receipt-current-as-planned",
  });
  const associationBase = task551ReceiptAssociations(TASK551_QUERY_INVENTORY, PLANNED_QUERY_DELTAS);
  const [associationId, associationValue] =
    Object.entries(associationBase)[0] ?? fail("query_inventory_invalid", "fixture-association");
  const { [associationId]: _association, ...associationRest } = associationBase;
  return Object.freeze([
    createTask551ReceiptMutation(["discovered.id", "discovered.source", "discovered.source.file"], {
      discovered: mutateDiscovered({
        ...firstDiscovered.source,
        file: "core/services/receiptDiscoveryFile.ts",
      }),
    }),
    createTask551ReceiptMutation(
      ["discovered.id", "discovered.source", "discovered.source.symbol"],
      {
        discovered: mutateDiscovered({
          ...firstDiscovered.source,
          symbol: "receiptDiscoverySymbol",
        }),
      }
    ),
    createTask551ReceiptMutation(["discovered.id", "discovered.source", "discovered.source.line"], {
      discovered: mutateDiscovered({
        ...firstDiscovered.source,
        line: firstDiscovered.source.line + 1,
      }),
    }),
    createTask551ReceiptMutation(
      ["discovered.id", "discovered.source", "discovered.source.column"],
      {
        discovered: mutateDiscovered({
          ...firstDiscovered.source,
          column: firstDiscovered.source.column + 1,
        }),
      }
    ),
    createTask551ReceiptMutation(
      [
        "discovered.id",
        "discovered.caller",
        "discovered.caller.family",
        "discovered.caller.operation",
      ],
      {
        discovered: mutateDiscovered(firstDiscovered.source, {
          family: "postgres-client",
          operation: "postgres",
        }),
      }
    ),
    createTask551ReceiptMutation(
      [
        "record.recordState",
        "record.id",
        "record.source",
        "record.source.file",
        "record.source.symbol",
        "record.source.line",
        "record.source.column",
      ],
      { current: replaceTask551ReceiptRecord(TASK551_QUERY_INVENTORY, current, currentAsPlanned) }
    ),
    createTask551ReceiptMutation(["record.id"], {
      planned: changedPlanned({ id: "receipt-planned-mutated" }),
    }),
    createTask551ReceiptMutation(["record.source", "record.source.file"], {
      planned: changedPlanned({
        source: { ...planned.source, file: "core/services/receiptRecordFile.ts" },
      }),
    }),
    createTask551ReceiptMutation(["record.source", "record.source.symbol"], {
      planned: changedPlanned({ source: { ...planned.source, symbol: "receiptRecordSymbol" } }),
    }),
    createTask551ReceiptMutation(["record.source", "record.source.line"], {
      current: changedCurrent({ source: { ...current.source, line: current.source.line! + 1 } }),
    }),
    createTask551ReceiptMutation(["record.source", "record.source.column"], {
      current: changedCurrent({
        source: { ...current.source, column: current.source.column! + 1 },
      }),
    }),
    createTask551ReceiptMutation(
      ["record.id", "record.caller", "record.caller.family", "record.caller.operation"],
      { current: changedCurrent({ caller: { family: "postgres-client", operation: "postgres" } }) }
    ),
    createTask551ReceiptMutation(["record.kind"], { planned: changedPlanned({ kind: "list" }) }),
    createTask551ReceiptMutation(["record.statementRole"], {
      planned: changedPlanned({ statementRole: "page" }),
    }),
    createTask551ReceiptMutation(["record.projectionSensitivity"], {
      planned: changedPlanned({ projectionSensitivity: "narrow" }),
    }),
    createTask551ReceiptMutation(["record.filterShape"], {
      planned: changedPlanned({ filterShape: "none" }),
    }),
    createTask551ReceiptMutation(["record.joinShape"], {
      planned: changedPlanned({ joinShape: "none" }),
    }),
    createTask551ReceiptMutation(["record.orderShape"], {
      planned: changedPlanned({ orderShape: "not-applicable" }),
    }),
    createTask551ReceiptMutation(["record.bound"], { planned: changedPlanned({ bound: 2 }) }),
    createTask551ReceiptMutation(["record.queryCountBudget"], {
      planned: changedPlanned({ queryCountBudget: 2 }),
    }),
    createTask551ReceiptMutation(["record.cacheEligibility", "record.freshnessPolicy"], {
      planned: changedPlanned({
        cacheEligibility: "ineligible",
        freshnessPolicy: "not-applicable",
      }),
    }),
    createTask551ReceiptMutation(["record.transactionMode", "record.constraintOwner"], {
      planned: changedPlanned({
        transactionMode: "transaction",
        constraintOwner: "database-existing",
      }),
    }),
    createTask551ReceiptMutation(["record.budgetId"], {
      planned: changedPlanned({ budgetId: "receipt-budget-mutated" }),
    }),
    createTask551ReceiptMutation(["record.plannedShapeId"], {
      planned: changedPlanned({ plannedShapeId: "receipt-shape-mutated" }),
    }),
    createTask551ReceiptMutation(["record.telemetryFingerprintKey"], {
      planned: changedPlanned({ telemetryFingerprintKey: "task551_receipt_mutation" }),
    }),
    createTask551ReceiptMutation(["record.owner"], {
      planned: changedPlanned({ owner: "TASK-551-03-L03" }),
    }),
    createTask551ReceiptMutation(["record.disposition"], {
      planned: changedPlanned({ disposition: "preserve-bounded" }),
    }),
    createTask551ReceiptMutation(["association", "association.id"], {
      associations: Object.freeze({
        ...associationRest,
        [`${associationId}-receipt`]: associationValue,
      }),
    }),
    createTask551ReceiptMutation(["association", "association.value"], {
      associations: Object.freeze({
        ...associationBase,
        [associationId]: `${associationValue}_receipt`,
      }),
    }),
    createTask551ReceiptMutation(["association", "association.count"], {
      associations: removeTask551Association(associationBase),
    }),
    createTask551ReceiptMutation(["count.discovered"], {
      discovered: Object.freeze(discovered.slice(1)),
    }),
    createTask551ReceiptMutation(["count.current"], {
      current: Object.freeze(TASK551_QUERY_INVENTORY.filter((record) => record.id !== current.id)),
    }),
    createTask551ReceiptMutation(["count.planned-admin"], {
      planned: Object.freeze(
        PLANNED_QUERY_DELTAS.filter((record) => record.id !== adminPlanned.id)
      ),
    }),
    createTask551ReceiptMutation(["count.planned-legacy"], {
      planned: Object.freeze(
        PLANNED_QUERY_DELTAS.filter((record) => record.id !== legacyPlanned.id)
      ),
    }),
  ]);
}

export type Task551RequiredFieldRemoval = Readonly<{
  target: "discovered" | "record" | "receipt";
  field: string;
  value: unknown;
}>;

function withoutTask551Field(
  value: Readonly<Record<string, unknown>>,
  field: string
): Readonly<Record<string, unknown>> {
  const { [field]: _removed, ...remaining } = value;
  return Object.freeze(remaining);
}

/** Required-field deletion cases remain invalid before receipt comparison. */
export function createTask551RequiredFieldRemovals(): readonly Task551RequiredFieldRemoval[] {
  const record = task551ReceiptRecord(
    TASK551_QUERY_INVENTORY,
    (candidate) => candidate.disposition !== "external-handoff"
  );
  const discovered =
    createTask551FixtureDiscoveredCallers()[0] ??
    fail("query_inventory_invalid", "fixture-discovery");
  const remove = (
    target: Task551RequiredFieldRemoval["target"],
    field: string,
    value: unknown
  ): Task551RequiredFieldRemoval => Object.freeze({ target, field, value });
  return Object.freeze([
    ...Object.keys(record).map((field) =>
      remove("record", `record.${field}`, withoutTask551Field(record, field))
    ),
    ...Object.keys(record.source).map((field) =>
      remove("record", `record.source.${field}`, {
        ...record,
        source: withoutTask551Field(record.source, field),
      })
    ),
    ...Object.keys(record.caller).map((field) =>
      remove("record", `record.caller.${field}`, {
        ...record,
        caller: withoutTask551Field(record.caller, field),
      })
    ),
    ...Object.keys(discovered).map((field) =>
      remove("discovered", `discovered.${field}`, withoutTask551Field(discovered, field))
    ),
    ...Object.keys(discovered.source).map((field) =>
      remove("discovered", `discovered.source.${field}`, {
        ...discovered,
        source: withoutTask551Field(discovered.source, field),
      })
    ),
    ...Object.keys(discovered.caller).map((field) =>
      remove("discovered", `discovered.caller.${field}`, {
        ...discovered,
        caller: withoutTask551Field(discovered.caller, field),
      })
    ),
    ...Object.keys(TASK551_QUERY_INVENTORY_RECEIPT).map((field) =>
      remove(
        "receipt",
        `receipt.${field}`,
        withoutTask551Field(TASK551_QUERY_INVENTORY_RECEIPT, field)
      )
    ),
  ]);
}

/**
 * DB-free in-memory source-traversal builders shared by the focused L01 suite.
 * They intentionally expose no runtime/test-framework dependency.
 */
export function createInMemoryInventoryScanIo(
  files: Readonly<Record<string, string>>,
  options: Readonly<{ symlink?: boolean; unreadable?: boolean }> = {}
): InventoryScanIo {
  const directories = new Map<string, Set<string>>([["core", new Set()]]);
  for (const file of Object.keys(files)) {
    const parts = file.split("/");
    let parent = "";
    for (let index = 0; index < parts.length - 1; index += 1) {
      const next = parent === "" ? parts[index]! : `${parent}/${parts[index]!}`;
      if (!directories.has(next)) directories.set(next, new Set());
      if (parent !== "") directories.get(parent)!.add(parts[index]!);
      parent = next;
    }
    directories.get(parent)!.add(parts.at(-1)!);
  }
  return {
    async readDirectory(directory) {
      const children = directories.get(directory);
      if (children === undefined) throw new Error("unreadable");
      return [...children].map((name) => {
        const child = `${directory}/${name}`;
        if (options.symlink && child === "core/link.ts") return { name, kind: "symlink" as const };
        return { name, kind: directories.has(child) ? ("directory" as const) : ("file" as const) };
      });
    },
    async readUtf8(file) {
      if (options.unreadable) throw new Error("unreadable");
      const value = files[file];
      if (value === undefined) throw new Error("missing");
      return value;
    },
  };
}

type ReadGate = Readonly<{ promise: Promise<void>; release: () => void }>;

function readGate(): ReadGate {
  let resolve: (() => void) | undefined;
  const promise = new Promise<void>((complete) => {
    resolve = complete;
  });
  return Object.freeze({ promise, release: () => resolve?.() });
}

export function createControlledInventoryScanIo(
  files: Readonly<Record<string, string>>,
  failingFiles: ReadonlySet<string> = new Set()
): Readonly<{
  io: InventoryScanIo;
  release: (file: string) => void;
  waitForReadStarts: (minimum: number) => Promise<void>;
  maxInFlight: () => number;
}> {
  const base = createInMemoryInventoryScanIo(files);
  const gates = new Map<string, ReadGate>();
  for (const file of Object.keys(files)) gates.set(file, readGate());
  let starts = 0;
  let inFlight = 0;
  let maxInFlight = 0;
  const waiters: Array<Readonly<{ minimum: number; resolve: () => void }>> = [];
  const resolveWaiters = (): void => {
    for (let index = waiters.length - 1; index >= 0; index -= 1) {
      const waiter = waiters[index]!;
      if (starts >= waiter.minimum) {
        waiters.splice(index, 1);
        waiter.resolve();
      }
    }
  };
  return Object.freeze({
    io: {
      readDirectory: base.readDirectory,
      async readUtf8(file) {
        const gate = gates.get(file);
        if (gate === undefined) throw new Error("unexpected-file");
        starts += 1;
        inFlight += 1;
        maxInFlight = Math.max(maxInFlight, inFlight);
        resolveWaiters();
        try {
          await gate.promise;
          if (failingFiles.has(file)) throw new Error("controlled-read-failure");
          return await base.readUtf8(file);
        } finally {
          inFlight -= 1;
        }
      },
    },
    release(file) {
      const gate = gates.get(file);
      if (gate === undefined) throw new Error("unknown-gate");
      gate.release();
    },
    waitForReadStarts(minimum) {
      if (starts >= minimum) return Promise.resolve();
      return new Promise<void>((resolve) => waiters.push(Object.freeze({ minimum, resolve })));
    },
    maxInFlight: () => maxInFlight,
  });
}
